# Группа серверов-воркеров
upstream app_backend {
    least_conn;    # новый запрос — тому, кто меньше занят
    # После 3 ошибок сервер исключается на 10 секунд
    server app1:8000 max_fails=3 fail_timeout=10s;
    server app2:8000 max_fails=3 fail_timeout=10s;
    server app3:8000 max_fails=3 fail_timeout=10s;
    # Держим соединения к воркерам открытыми
    keepalive 32;
}

server {
    listen 80;

    location = /nginx-health {
        access_log off;
        return 200 "ok\n";
    }

    location / {
        proxy_pass http://app_backend;
        proxy_http_version 1.1;          # нужно для keepalive
        proxy_set_header Connection "";

        # Передаём воркеру данные о реальном клиенте
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;

        # Воркер упал — повторить запрос на другом
        # (POST не повторяется: иначе можно создать заказ дважды)
        proxy_next_upstream error timeout http_502 http_503;
        proxy_connect_timeout 2s;
        proxy_read_timeout 30s;

        # Для наглядности: адрес воркера, обработавшего запрос
        add_header X-Upstream $upstream_addr always;
    }
}

